{"command": "cd /home/zhouhuijuan1987/wiki-openclaw/youtube-video-research-wiki && python3 -c "
import re, glob
files = {f.replace('wiki/','').rsplit('.md',1)[0].lower() for f in glob.glob('wiki/**/*.md',recursive=True)}
dead = []
for f in glob.glob('wiki/**/*.md',recursive=True):
    for m in re.finditer(r'\[\[([^\]]+?)(?:\|[^\]]+)?\]\]', open(f).read()):
        link = m.group(1).strip().lower()
        if link not in files and not any(link == s.split('/')[-1] for s in files):
            dead.append((f, m.group(1)))
for f, l in sorted(set(dead)):
    print(f'{f}: [[{l}]]')
print(f'\\nTotal unique dead links: {len(set(dead))}')
""}
